package main

import (
	"encoding/json"
	"net/http"
	"os"
)

type Item struct {
	ID   int    `json:"id"`
	Name string `json:"name"`
}

var (
	items  []Item
	nextID = 1
	contract = map[string]interface{}{
		"openapi": "3.0.0",
		"info":    map[string]string{"title": "Contract Test API", "version": "1.0.0"},
		"paths": map[string]interface{}{
			"/items": map[string]interface{}{
				"post": map[string]interface{}{
					"requestBody": map[string]interface{}{
						"required":   []string{"name"},
						"properties": map[string]interface{}{"name": map[string]string{"type": "string"}},
					},
					"responses": map[string]interface{}{
						"201": map[string]interface{}{
							"properties": map[string]interface{}{
								"id":   map[string]string{"type": "number"},
								"name": map[string]string{"type": "string"},
							},
						},
					},
				},
			},
		},
	}
)

func main() {
	port := os.Getenv("PORT")
	if port == "" { port = "3000" }

	http.HandleFunc("/api/contract", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(contract)
	})

	http.HandleFunc("/items", func(w http.ResponseWriter, r *http.Request) {
		var body struct{ Name string `json:"name"` }
		json.NewDecoder(r.Body).Decode(&body)
		item := Item{ID: nextID, Name: body.Name}
		nextID++
		items = append(items, item)
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusCreated)
		json.NewEncoder(w).Encode(item)
	})

	http.ListenAndServe(":"+port, nil)
}

